INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (3.414, 62, 190805, 2, "2025/01/31 12:00:00", "カリン", 1, "ミッションをクリアすると、\n報酬がもらえますよ！\n頑張ってください", "2030/01/01 14:59:59", 1000001, 1, 1, 0.0, -416.5);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (3.099, 62, 190805, 2, "2025/01/31 12:00:00", "カリン", 1, "ミッションをクリアして、\n報酬をゲットしましょう！", "2030/01/01 14:59:59", 1000002, 2, 1, 0.0, -416.5);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2.801, 63, 190805, 2, "2025/01/31 12:00:00", "カリン", 1, "受け取ることができる\n報酬があるようです\n確認してみてください", "2030/01/01 14:59:59", 1000003, 3, 1, 0.0, -416.5);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, 63, 190805, 2, "2025/01/31 12:00:00", "カリン", 2, "報酬がもらえますよ！\nチェックしてみてください", "2030/01/01 14:59:59", 1000004, 4, 1, 0.0, -416.5);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2.12, 64, 190805, 1, "2025/01/31 12:00:00", "カリン", 2, "ギルド管理協会です！\nイベント報酬券をお持ちでしたら、様々なアイテムと交換できますよ", "2030/01/01 14:59:59", 1000005, 5, 1, 0.0, -363.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1.68, 64, 190805, 2, "2025/01/31 12:00:00", "カリン", 1, "お疲れさまです！\nこちらでイベント報酬券とアイテムを交換することができますよ", "2030/01/01 14:59:59", 1000006, 6, 1, 0.0, -363.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2.33, 64, 190805, 1, "2025/01/31 12:00:00", "カリン", 2, "いつもありがとうございます！\n報酬交換ですか？\nでは、イベント報酬券とお引き換えいたしますね", "2030/01/01 14:59:59", 1000007, 7, 1, 0.0, -363.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (5.18, 61, 133701, 7, "2025/01/31 12:00:00", "ラビリスタ", 3, "今度の敵は、アタシにとっても\n放ってはおけない存在だ\n少年、アタシも全力で行くからさ\n一緒に守ろう、この世界を", "2030/01/01 14:59:59", 1020101, 101, 10201, -6.0, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (8.77, 61, 133901, 2, "2025/01/31 12:00:00", "クリスティーナ", 1, "退屈の吹き飛ぶような\n戦いの気配がするなぁ坊や\nさっさとワタシをそこへ連れてゆけ\n世界も守ってやるさ、ついでにな", "2030/01/01 14:59:59", 1020102, 201, 10201, -2.0, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (15.5, 61, 133801, 1, "2025/01/31 12:00:00", "ネネカ", 6, "おや、私の力が必要……と？\nグレゴールが手伝うそうですよ\n私は戦わないのか、という顔ですね\n……考えておきます", "2030/01/01 14:59:59", 1020103, 301, 10201, 0.0, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (9.061, 61, 134301, 5, "2025/02/28 12:00:00", "ランファ", 2, "わたしだけの歌…\n一緒に、探してくれる…？\nあなたがいれば…\nもっとがんばれるから…", "2030/01/01 14:59:59", 1020201, 101, 10202, 0.0, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (7.699, 61, 134401, 2, "2025/02/28 12:00:00", "チカ", 1, "同じ唱喚士として、仲間として\n私にできることをします\n…これも、あなたが\n背中を押してくれたおかげですよ", "2030/01/01 14:59:59", 1020202, 201, 10202, 0.0, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (8.595, 61, 134601, 2, "2025/03/31 12:00:00", "アオイ", 1, "世界の平和が私とクローチェさんに\nかかってるんですよね？\nぼっちには過大すぎる期待ですけど\nふ、二人でなら背負ってみせます！", "2030/01/01 14:59:59", 1020301, 101, 10203, 0.0, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (7.758, 61, 134501, 2, "2025/03/31 12:00:00", "クローチェ", 1, "新しく手に入れたこの翼で…\nナイトさんがどこにいたって\nわたし、駆けつけちゃいますよっ！\nクローチェ・エアリアル発進ですっ", "2030/01/01 14:59:59", 1020302, 201, 10203, 0.0, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (7.0, 61, 132302, 6, "2025/04/30 12:00:00", "ルイズマリー", 2, "今日はダーリンとの初デート♪\n二人でショッピングして、その後は\n…って私、指名手配されてる！？\nちょ、た…助けてダーリン～！！", "2030/01/01 14:59:59", 1020401, 101, 10204, 0.0, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (7.904, 61, 132402, 2, "2025/04/30 12:00:00", "イロハ", 1, "ルイちゃんのおばあちゃん優しくて\nいつもにこにこで、イロハ大好き♪\nでも一番好きなのは、角がすっごく\n大きくてかっこいいとこなんだ～♪", "2030/01/01 14:59:59", 1020402, 201, 10204, 0.0, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (8.487, 61, 132502, 2, "2025/04/30 12:00:00", "ソノ", 4, "ノゾミちゃんのおかげで売上が安定\nしてきたのに、臨時休業、痛すぎる\n…ま、ルイちゃんのために\n一肌脱ぐか。行くよイロハ～", "2030/01/01 14:59:59", 1020403, 301, 10204, 0.0, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (8.763, 61, 134901, 2, "2025/05/31 12:00:00", "カノン", 1, "ヲ～ッホッホ♪\nあたくし様と同じお空気を吸える\nお幸運を噛みしめなさいですわ～♪\nヲ～ッホッホッホ～♪", "2030/01/01 14:59:59", 1020502, 101, 10205, 0.0, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (6.417, 61, 134801, 3, "2025/05/31 12:00:00", "ツムギ", 1, "いきますよ騎士さん！\nカノンさんと力を合わせて…力を…\n…本当にあの人なんなんです？\nこれまでになく不安なんですけど！", "2030/01/01 14:59:59", 1020503, 201, 10205, 0.0, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (10.335, 61, 135001, 7, "2025/06/30 12:00:00", "エリス", 3, "『願いが叶う海岸』か…怪しい\nだというのに、阿賀斗紫布菜たちは\n呑気に戯れている…見ていられない\n騎士クンは、わたしが守ってみせる", "2030/01/01 14:59:59", 1020601, 101, 10206, 0.0, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (6.281, 61, 135101, 4, "2025/06/30 12:00:00", "シェフィ", 2, "せっかくの夏休みなんだし\nたまにはビーチでゆっくりしましょ\n…え、もしかしてこの夏もあんまり\n休めなかったりする感じなの？", "2030/01/01 14:59:59", 1020602, 201, 10206, 0.0, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (12.244, 61, 135201, 2, "2025/06/30 12:00:00", "プレシア", 1, "いっぱい。たべて\nおおきく。なると\nせーぎ。まもれる。はず\nお兄。いっしょに。スイカ。たべよ", "2030/01/01 14:59:59", 1020603, 301, 10206, 0.0, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (6.339, 61, 135301, 8, "2025/07/31 12:00:00", "クリア", 2, "ひと夏の冒険のはじまりです！\nアネモネさんも楽しんでくれたら\n…できれば、もう少し\n仲良くなれたらうれしいな…", "2030/01/01 14:59:59", 1020701, 101, 10207, 0.0, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (8.184, 61, 135401, 9, "2025/07/31 12:00:00", "アネモネ", 7, "─幻の花…\n本当にあるのか謎─ですけど\n探すくらいは、\n付き合ってもいいです", "2030/01/01 14:59:59", 1020702, 201, 10207, 0.0, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (3.906, 61, 129101, 2, "2025/08/31 12:00:00", "アイラ", 9, "あははっ！　笑う門には福来る！\n笑ってればきっと、複製世界にも\n未来はやってくるって信じてる！\nそうだよね、シナツちゃん！", "2030/01/01 14:59:59", 1020801, 101, 10208, 0.0, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (14.465, 61, 129201, 2, "2025/08/31 12:00:00", "シナツ", 1, "繰り返されるリセットの先の未来\n何度願っても手に入らなかった未来\n…でも、私は諦めない。絶対にだ\nキミも同じだろ…アイラ？", "2030/01/01 14:59:59", 1020802, 201, 10208, 0.0, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (8.662, 61, 100101, 3, "2025/08/31 12:00:00", "ヒヨリ", 4, "アイラの世界のみんなも、\n一生懸命生きてるんだ…！\n…なのに、世界の危機だなんて！\nあたし、絶対、絶対力になるよ！", "2030/01/01 14:59:59", 1020803, 301, 10208, 0.0, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (10.915, 61, 100301, 3, "2025/08/31 12:00:00", "レイ", 1, "シナツ…もう一人の私\n彼女が大切にしている世界を\n絶対に終わらせはしない…！\n彼女と笑い合える未来のために！", "2030/01/01 14:59:59", 1020804, 401, 10208, 0.0, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (6.042, 61, 135802, 7, "2025/09/30 12:00:00", "ユキノ", 1, "あ、ど、ども…\nあ、あんま見ねぇでくれっと\nその、恥ずかしくて…\n体が熱くなって、溶けちまう…", "2030/01/01 14:59:59", 1020901, 101, 10209, 0.0, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (9.402, 61, 135903, 1, "2025/09/30 12:00:00", "サツキ", 4, "なんで俺が幽霊に…意味不明だ\nこれじゃ死んでも死にきれねェ\n悪ィがこれも何かの縁だ、\nよろしく頼むぜ騎士公", "2030/01/01 14:59:59", 1020902, 201, 10209, 0.0, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (8.16, 61, 136902, 1, "2025/09/30 12:00:00", "ルルィ", 8, "う、うじゅる…\nサツキ姉しゃまを助けるためにも\nまずは、腹ごしらえでしゅね…！\nタコ焼き、召し上がってくだしゃい", "2030/01/01 14:59:59", 1020903, 301, 10209, 0.0, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (5.0, 61, 137401, 2, "2025/10/31 12:00:00", "カスミ", 3, "ひさしぶりのジオ・ゲヘナ\n歓迎パーティーで起きた殺人事件！\nランドソルの名探偵の名にかけて\n解き明かしてみせようじゃないか！", "2030/01/01 14:59:59", 1021001, 101, 10210, 0.0, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (8.12, 61, 136001, 1, "2025/10/31 12:00:00", "アラクネ", 4, "…わたしはどこの誰なのでしょう\nどこから来てどこへ行くのでしょう\nこの事件の真相が分かれば、\n何かが掴めるような気がいたします", "2030/01/01 14:59:59", 1021002, 201, 10210, 0.0, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (6.386, 61, 136202, 2, "2025/10/31 12:00:00", "ナーナ", 4, "ナーナ、すいりとかろんぱとか、\nむずかしくてわかんないけど…\nお友だちとドーナツのためならっ\nせーいっぱいがんばるよっ！", "2030/01/01 14:59:59", 1021003, 301, 10210, 0.0, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (7.438, 61, 136402, 4, "2025/11/30 12:00:00", "ユイ", 3, "騎士クンに想いを伝えたい…だから\nミソラちゃん、わたしがんばるね！\n…あれ？　わたし、なんでこんなに\n必死になってるんだろう…？", "2030/01/01 14:59:59", 1021101, 101, 10211, 0.0, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (8.35, 61, 136302, 5, "2025/11/30 12:00:00", "ミソラ", 1, "騎士さんとのデートはわたしに\nお任せです★　なのでユイさんは\n安心して計画に専念して…たくさん\nドキドキしちゃってくださいね", "2030/01/01 14:59:59", 1021102, 201, 10211, 0.0, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (5.0, 61, 136501, 2, "2025/12/31 12:00:00", "シズル", 1, "新しい年がやってくるね！\nお正月の料理も飾りつけも、\nお姉ちゃんにお任せだよ♪\nみんなで楽しく新年を迎えよう！", "2030/01/01 14:59:59", 1021201, 101, 10212, 0.0, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (5.25, 61, 137902, 2, "2025/12/31 12:00:00", "リノ", 1, "おうちの掃除もトラブルも、 \n世界を揺るがす大ピンチも！\n今年のことは今年のうちに \nサッサと片付けちゃいますっ！", "2030/01/01 14:59:59", 1021202, 201, 10212, 0.0, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (7.5, 61, 106801, 2, "2025/12/31 12:00:00", "ラビリスタ", 1, "年の瀬はギルドマスターも\nつい駆け回っちゃう忙しい時期だ！\n一年いろいろあったけど\nお互いイイ年を迎えよう、少年！", "2030/01/01 14:59:59", 1021203, 301, 10212, 0.0, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (8.204, 61, 126501, 2, "2026/01/31 12:00:00", "ライラエル", 1, "漂う異国の料理の香り…それだけで\n世界中を旅した気分に浸れますね\nふふ、ほらクローチェ\nあまりはしゃぎすぎないように…♪", "2030/01/01 14:59:59", 1021301, 101, 10213, 0.0, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (7.176, 61, 129701, 2, "2026/01/31 12:00:00", "ネフィ＝ネラ", 1, "異界の姫君と煮炊きにて競い合う…\n感奮興起、いとをかし\n華やかなる祭典と相成るよう、一肌\n脱がせていただきとう存じまする", "2030/01/01 14:59:59", 1021302, 201, 10213, 0.0, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (8.602, 61, 133101, 5, "2026/01/31 12:00:00", "ヴァイオレット", 1, "『ビストロプリンセス』のために\n料理の特訓を重ねてまいりました\nこの料理で騎士様の…い、いえ\n皆様の心とお腹を満たしますわ！", "2030/01/01 14:59:59", 1021303, 301, 10213, 0.0, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (10.14, 61, 138101, 3, "2026/02/06 12:00:00", "ライラエル", 1, "多様な味わいが織りなすハーモニー\nそれこそが我が国の矜持です\nもしもそれを乱すようであれば\nわたしも優しくはありませんよ？", "2030/01/01 14:59:59", 1021304, 102, 10213, 0.0, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (10.152, 61, 138201, 7, "2026/02/06 12:00:00", "ネフィ＝ネラ", 1, "煉獄の穢土にてひと際輝く民草の心\n此れを守護りまするがわっちの責務\n如何な困難待ち受けようと\n不退転の矜持に揺らぎはありんせん", "2030/01/01 14:59:59", 1021305, 202, 10213, 0.0, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (9.688, 61, 138001, 3, "2026/02/06 12:00:00", "ヴァイオレット", 4, "裏世界の皆様は危機を脱し、\n残るはランドソルの皆様のみ…\n彼らを救い出すために、どうか…\nお立ち下さいペコリーヌ姫…！", "2030/01/01 14:59:59", 1021306, 302, 10213, 0.0, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (5.928, 61, 138301, 1, "2026/02/12 12:00:00", "ペコリーヌ", 2, "みなさん、お待たせしちゃいました\nペコリーヌ、完全復活です☆\nみなさんの食卓を守るため\nもう二度と、わたしはめげません！", "2030/01/01 14:59:59", 1021307, 401, 10213, 0.0, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (9.19, 61, 138702, 2, "2026/02/28 12:00:00", "ワカナ", 4, "成行きで参加することになっちゃっ\nた尻相撲大会。ううっ、恥ずかしい\nけどやるしかないよね。…騎士さん\nいっぱい応援してくださいね？", "2030/01/01 14:59:59", 1021401, 101, 10214, 0.0, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (8.724, 61, 138802, 3, "2026/02/28 12:00:00", "シオリ", 1, "「お姉ちゃんを守れる自分になる」\nあの日の約束、今こそ果たしてみせ\nます。例えお姉ちゃんに背くことに\nなっても。例えそれが尻相撲でも！", "2030/01/01 14:59:59", 1021402, 201, 10214, 0.0, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (7.758, 61, 138902, 1, "2026/03/31 12:00:00", "グレイス", 4, "私がへんたいふしんしゃさんって…\nただ生きているだけなのに、ひどい\n…まぁ死んでるんですけど…とか\n言ってる暇もない感じですか？", "2030/01/01 14:59:59", 1021501, 101, 10215, 0.0, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (6.375, 61, 139002, 4, "2026/03/31 12:00:00", "キョウカ", 6, "あの、助けてください！\n私がへんたいふしんしゃさんに\nなっちゃったみたいなんです…！\nどういう意味かは私もわかりません", "2030/01/01 14:59:59", 1021502, 201, 10215, 0.0, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (6.173, 61, 136902, 1, "2026/03/31 12:00:00", "ルルィ", 6, "ましゃか、グレイス姉しゃまたちが\nへんたいふしんしゃさんだなんて…\n騎士しゃん。あたちたちも協力ちて\n二人の破滅エンドを回避ちましょう", "2030/01/01 14:59:59", 1021503, 301, 10215, 0.0, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (4.202, 61, 139202, 2, "2026/04/30 12:00:00", "ミホ", 6, "違う世界に来ちゃうし、\n驚きの連続だけど…\nわたしも精いっぱい頑張ります！\nアストルムのみんなと一緒に！", "2030/01/01 14:59:59", 1021601, 101, 10216, 0.0, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2.842, 61, 139302, 1, "2026/04/30 12:00:00", "マホ", 6, "想定外の事象が発生したな…だが\nいかなる苦境も切り抜けてみせる\nいつもの自分とは違う姿になっても\nわたしはわたし、西住流だ", "2030/01/01 14:59:59", 1021602, 201, 10216, 0.0, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (4.598, 61, 139402, 1, "2026/04/30 12:00:00", "エリカ", 4, "何でこんなことになっているのか\n全然わからないけど、迷ってる暇は\nないわ。黒森峰の次期隊長として、\n前進あるのみ！　これも戦車道よ！", "2030/01/01 14:59:59", 1021603, 301, 10216, 0.0, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (6.533, 61, 125802, 3, "2026/05/31 12:00:00", "リリ", 4, "わたくしたちの悲願は、ロストさせ\nてしまった方々をお助けすること…\nそのためなら、どのような辛苦にも\n耐え抜いてみせます…！", "2030/01/01 14:59:59", 1021701, 101, 10217, 0.0, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (5.0, 61, 126102, 3, "2026/05/31 12:00:00", "プレシア", 3, "みんなも。せーぎも。\nクリアも。パパ、も。\nぜったい、たすける。\nみててね。お兄。", "2030/01/01 14:59:59", 1021702, 301, 10217, 0.0, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (5.214, 61, 126002, 4, "2026/05/31 12:00:00", "クリア", 3, "癒しの力を使うこと…\nもう、ためらいません！\nモネちゃんやお兄さん…\nみんなに許してもらうためにも！", "2030/01/01 14:59:59", 1021703, 201, 10217, 0.0, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (8.781, 61, 139501, 3, "2026/05/31 12:00:00", "リリ", 1, "ヴァルキュリア─皆様を助けたい\nという願いを、力にできるのなら…\nわたくしたちは、きっと誰にも\n負けません！　一意専心です…！", "2030/01/01 14:59:59", 1021704, 102, 10217, 0.0, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (6.529, 61, 139601, 1, "2026/05/31 12:00:00", "クリア", 2, "このヴァルキュリアって職業、\nまるで天使みたいな格好ですよね\nうーん…『聖女』ちゃんって\n呼ばれるよりは、マシかな？", "2030/01/01 14:59:59", 1021705, 202, 10217, 0.0, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (3.195, 61, 139701, 2, "2026/05/31 12:00:00", "プレシア", 3, "ばるきり。もーど。\nはね。まっしろ。\nはっぴーちゃんと。おなじ。\nいいかんじ。", "2030/01/01 14:59:59", 1021706, 302, 10217, 0.0, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (12.43, 61, 139902, 3, "2026/06/30 12:00:00", "ルイズマリー", 2, "ダーリンと一緒に南の島で\nリゾート開発なんて夢みたい♪\nああ…幸せ、最高の夏だわ…\n触れたら爆発さえしなければ～…っ", "2030/01/01 14:59:59", 1021801, 101, 10218, 0.0, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (6.35, 61, 140001, 3, "2026/06/30 12:00:00", "クレジッタ", 2, "青い空、白い雲…無人島リゾートで\n大儲けですわ～♪　こらこらそこ、\nイチャついてるんじゃないですのよ\n触れたらドカンですわよ、ドカン！", "2030/01/01 14:59:59", 1021802, 201, 10218, 0.0, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (10.23, 61, 140102, 5, "2026/07/31 12:00:00", "フブキ", 1, "みんなはかわいいぼくを見られて、\nぼくはみんなからラヴをもらう♡\n最高のウィンウィンだよね、これ♡\nで、最後はお兄さんをドレーに…♡", "2030/01/01 14:59:59", 1021901, 101, 10219, 0.0, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (5.584, 61, 140201, 2, "2026/07/31 12:00:00", "ヴァンピィ", 1, "けんぞくとたくさん遊ぶためにも、\nみんなからラヴをもらわなくちゃ♪\nバズっちゃおー作戦、\n一緒に考えてね！　けんぞくぅ♪", "2030/01/01 14:59:59", 1021902, 201, 10219, 0.0, -285.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (3.414, 62, 190801, 2, "2026/04/10 12:00:00", "カリン", 1, "ミッションをクリアすると、\n報酬がもらえますよ！\n頑張ってください", "2030/01/01 14:59:59", 2000001, 1, 2, 0.0, -416.5);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (3.099, 62, 190801, 2, "2026/04/10 12:00:00", "カリン", 1, "ミッションをクリアして、\n報酬をゲットしましょう！", "2030/01/01 14:59:59", 2000002, 2, 2, 0.0, -416.5);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2.801, 63, 190801, 2, "2026/04/10 12:00:00", "カリン", 1, "受け取ることができる\n報酬があるようです\n確認してみてください", "2030/01/01 14:59:59", 2000003, 3, 2, 0.0, -416.5);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, 63, 190801, 2, "2026/04/10 12:00:00", "カリン", 2, "報酬がもらえますよ！\nチェックしてみてください", "2030/01/01 14:59:59", 2000004, 4, 2, 0.0, -416.5);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2.12, 64, 190801, 1, "2026/04/10 12:00:00", "カリン", 2, "ギルド管理協会です！\nイベント報酬券をお持ちでしたら、様々なアイテムと交換できますよ", "2030/01/01 14:59:59", 2000005, 5, 2, 0.0, -363.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1.68, 64, 190801, 2, "2026/04/10 12:00:00", "カリン", 1, "お疲れさまです！\nこちらでイベント報酬券とアイテムを交換することができますよ", "2030/01/01 14:59:59", 2000006, 6, 2, 0.0, -363.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2.33, 64, 190801, 1, "2026/04/10 12:00:00", "カリン", 2, "いつもありがとうございます！\n報酬交換ですか？\nでは、イベント報酬券とお引き換えいたしますね", "2030/01/01 14:59:59", 2000007, 7, 2, 0.0, -363.0);
